import { keccak256, stringToHex } from "viem";
import {
    encodeRelaySwapRouting,
    decodeRelaySwapRouting,
    RelaySwapRouting,
    RELAY_SWAP_ROUTING_TYPEHASH,
} from "./swap_routing_abi";

// CR-1 (relayer side): the relayer redefines the SwapRouting tuple ABI locally in
// `swap_routing_abi.ts` instead of importing the SDK's canonical `RELAY_SWAP_ROUTING_ABI`
// (constant/PoolSessionTransact.ts). The canonical constant is exported ONLY from the SDK's
// main entry, which cannot be imported here: jest cannot transform the `@noble/ciphers` ESM
// the main barrel pulls in (identical failure to the fee_abi.golden.spec.ts / pprouter_abi
// precedents — "Cannot use import statement outside a module"). So the two independent ABI
// copies are cross-checked indirectly: both must ABI-encode this identical tuple to these
// identical golden bytes. A field add / reorder / type change on the relayer's local tuple
// breaks this test; the same drift on the SDK's `RELAY_SWAP_ROUTING_ABI` (or the on-chain
// RelaySwaps.SwapRouting struct it mirrors) must be reconciled here. Keep the golden bytes
// in sync — they are the canonical RelaySwaps.SwapRouting ABI encoding.

const SWAP_TARGET = "0x1231deb6f5749ef6ce6943a275a1d3e7486f4eae" as const;
const APPROVAL_ADDRESS = "0x2222222222222222222222222222222222222222" as const;
const OUTPUT_TOKEN = "0x3333333333333333333333333333333333333333" as const;
const RECIPIENT = "0x70997970c51812dc3a010c7d01b50e0d17dc79c8" as const;
const FEE_RECIPIENT = "0xc1ebfda3114bc2496e86d466b3082491a96767df" as const;
const FALLBACK_ADDRESS = "0x5555555555555555555555555555555555555555" as const;
const DUST_RECIPIENT = "0x6666666666666666666666666666666666666666" as const;
const DUST_TOKEN_ID = "0x7777777777777777777777777777777777777777" as const;

const FULL: RelaySwapRouting = {
    swapTarget: SWAP_TARGET,
    approvalAddress: APPROVAL_ADDRESS,
    outputToken: OUTPUT_TOKEN,
    recipient: RECIPIENT,
    feeRecipient: FEE_RECIPIENT,
    fallbackAddress: FALLBACK_ADDRESS,
    dustRecipient: DUST_RECIPIENT,
    feeAmount: 123456789n,
    minOutputAmount: 987654321n,
    nativeGas: 42n,
    swapValue: 31337n,
    gasSwapMaxInput: 424242n,
    gasSwapCalldata: "0xc0ffee",
    swapCalldata: "0xdeadbeef",
    dustRescue: {
        chainId: 8453n,
        tokenId: DUST_TOKEN_ID,
        isCanonical: true,
        spendingPubKey: "0xaabbcc",
        viewingPubKey: "0xddeeff",
    },
};

const GOLDEN_FULL =
    "";

const ZERO: RelaySwapRouting = {
    swapTarget: SWAP_TARGET,
    approvalAddress: APPROVAL_ADDRESS,
    outputToken: OUTPUT_TOKEN,
    recipient: RECIPIENT,
    feeRecipient: FEE_RECIPIENT,
    fallbackAddress: FALLBACK_ADDRESS,
    dustRecipient: DUST_RECIPIENT,
    feeAmount: 0n,
    minOutputAmount: 0n,
    nativeGas: 0n,
    swapValue: 0n,
    gasSwapMaxInput: 0n,
    gasSwapCalldata: "0x",
    swapCalldata: "0x",
    dustRescue: {
        chainId: 0n,
        tokenId: "0x0000000000000000000000000000000000000000",
        isCanonical: false,
        spendingPubKey: "0x",
        viewingPubKey: "0x",
    },
};

const GOLDEN_ZERO =
    "";

describe("SwapRouting ABI drift — relayer swap_routing_abi vs canonical golden bytes", () => {
    it("encodeRelaySwapRouting matches the canonical fully-populated golden bytes", () => {
        expect(encodeRelaySwapRouting(FULL)).toBe(GOLDEN_FULL);
    });

    it("encodeRelaySwapRouting matches the canonical zero-value / empty-calldata golden bytes", () => {
        expect(encodeRelaySwapRouting(ZERO)).toBe(GOLDEN_ZERO);
    });

    it("decodeRelaySwapRouting is the byte-exact inverse of the encoder (decode -> re-encode == golden)", () => {
        // decodeAbiParameters returns checksummed addresses, so compare at the byte level
        // rather than field-by-field: re-encoding the decoded tuple must reproduce the golden.
        expect(encodeRelaySwapRouting(decodeRelaySwapRouting(GOLDEN_FULL))).toBe(GOLDEN_FULL);
    });
});

// RC-32: cross-checks the relayer's RELAY_SWAP_ROUTING_TYPEHASH against a keccak256 computed
// here from the same canonical encodeType string RelaySwaps.sol's ROUTING_TYPEHASH() hashes
// (see that function's NatSpec) -- independently reproduced rather than imported, the same
// principle as the ABI cross-check above. A field the FULL/ZERO fixtures above didn't catch
// (a rename, or a type change that happens to re-encode to the same byte length) fails here.
describe("SwapRouting layout typehash — relayer constant vs the canonical encodeType string", () => {
    it("RELAY_SWAP_ROUTING_TYPEHASH matches keccak256 of SwapRouting's EIP-712 encodeType string", () => {
        const encodeType =
            "SwapRouting(address swapTarget,address approvalAddress,address outputToken," +
            "address recipient,address feeRecipient,address fallbackAddress,address dustRecipient," +
            "uint256 feeAmount,uint256 minOutputAmount,uint256 nativeGas,uint256 swapValue," +
            "uint256 gasSwapMaxInput,bytes gasSwapCalldata,bytes swapCalldata,DustRescue dustRescue)" +
            "DustRescue(uint256 chainId,address tokenId,bool isCanonical,bytes spendingPubKey," +
            "bytes viewingPubKey)";
        expect(keccak256(stringToHex(encodeType))).toBe(RELAY_SWAP_ROUTING_TYPEHASH);
    });
});
